import pytest


def pick(xs: list[int], seed: int) -> int:
    """Return an element of the non-empty list xs chosen deterministically
    from seed: the same xs and seed always give the same element.

    Works for any integer seed, including negative and very large values.
    Uses no randomness. Raises ValueError if xs is empty.
    """
    if not xs:
        raise ValueError("xs must be non-empty")
    return xs[seed % len(xs)]


def test_pick_returns_element_of_list() -> None:
    xs = [10, 20, 30, 40]
    for seed in range(-10, 20):
        assert pick(xs, seed) in xs


def test_pick_is_deterministic() -> None:
    xs = [5, 6, 7, 8, 9]
    for seed in (0, 1, -1, 12345, -98765, 2**80):
        assert pick(xs, seed) == pick(xs, seed)


def test_pick_single_element() -> None:
    for seed in (0, 1, -7, 10**30):
        assert pick([42], seed) == 42


def test_pick_negative_seed() -> None:
    xs = [1, 2, 3]
    assert pick(xs, -5) in xs


def test_pick_huge_seed() -> None:
    xs = [1, 2, 3]
    assert pick(xs, 10**100) in xs
    assert pick(xs, -(10**100)) in xs


def test_pick_does_not_mutate_input() -> None:
    xs = [3, 1, 2]
    pick(xs, 7)
    assert xs == [3, 1, 2]


def test_pick_covers_all_elements_over_seeds() -> None:
    xs = [1, 2, 3, 4]
    seen = {pick(xs, seed) for seed in range(100)}
    assert seen == set(xs)


def test_pick_duplicates_allowed() -> None:
    xs = [7, 7, 7]
    assert pick(xs, 3) == 7


def test_pick_empty_raises() -> None:
    with pytest.raises(ValueError):
        pick([], 0)

